package remframework.geometry.discovery.realization.session;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

/** Human-readable persistence for intermediate manual experiments. */
public final class ManualRelaxationStore {
    /** Persist a force set together with the immutable runtime factor values. */
    public Path saveForceSetWithFactors(Path file,Set<ManualConstraint> active,ConstraintStrengthFactors factors)throws IOException{Properties p=new Properties();p.setProperty("format_version","2");p.setProperty("active_force_set",active.stream().map(Enum::name).sorted().reduce((a,b)->a+","+b).orElse(""));if(factors!=null)for(ManualConstraint c:ManualConstraint.values())p.setProperty("factor."+c.name(),Double.toString(factors.factor(c)));Path parent=file.toAbsolutePath().getParent();if(parent!=null)Files.createDirectories(parent);try(Writer writer=Files.newBufferedWriter(file,StandardCharsets.UTF_8)){p.store(writer,"REM Framework manual active force set");}return file;}
    public Path saveForceSetWithFactors(Path file,Set<ManualConstraint> active,ConstraintStrengthFactors factors,ConvexityMode mode)throws IOException{Path result=saveForceSetWithFactors(file,active,factors);Properties p=new Properties();try(Reader reader=Files.newBufferedReader(file,StandardCharsets.UTF_8)){p.load(reader);}p.setProperty("convexity_mode",(mode==null?ConvexityMode.LEGACY_CONVEXITY:mode).name());try(Writer writer=Files.newBufferedWriter(file,StandardCharsets.UTF_8)){p.store(writer,"REM Framework manual active force set");}return result;}
    public Map<ManualConstraint,Double> loadStrengthFactors(Path file)throws IOException{Properties p=new Properties();try(Reader reader=Files.newBufferedReader(file,StandardCharsets.UTF_8)){p.load(reader);}Map<ManualConstraint,Double> result=new EnumMap<>(ManualConstraint.class);for(ManualConstraint c:ManualConstraint.values())if(p.getProperty("factor."+c.name())!=null)result.put(c,Double.parseDouble(p.getProperty("factor."+c.name())));return Map.copyOf(result);}
    public ConvexityMode loadConvexityMode(Path file)throws IOException{Properties p=new Properties();try(Reader reader=Files.newBufferedReader(file,StandardCharsets.UTF_8)){p.load(reader);}return ConvexityMode.valueOf(p.getProperty("convexity_mode",ConvexityMode.LEGACY_CONVEXITY.name()));}
    public Path saveForceSet(Path file,Set<ManualConstraint> active)throws IOException{Properties p=new Properties();p.setProperty("format_version","1");p.setProperty("active_force_set",active.stream().map(Enum::name).sorted().reduce((a,b)->a+","+b).orElse(""));Path parent=file.toAbsolutePath().getParent();if(parent!=null)Files.createDirectories(parent);try(Writer writer=Files.newBufferedWriter(file,StandardCharsets.UTF_8)){p.store(writer,"REM Framework manual active force set");}return file;}
    public Set<ManualConstraint> loadForceSet(Path file)throws IOException{Properties p=new Properties();try(Reader reader=Files.newBufferedReader(file,StandardCharsets.UTF_8)){p.load(reader);}if(!"1".equals(p.getProperty("format_version")))throw new IOException("Unsupported force-set format.");String value=p.getProperty("active_force_set","");return value.isBlank()?Set.of():Set.copyOf(Arrays.stream(value.split(",")).filter(s->!s.isBlank()).map(ManualConstraint::valueOf).toList());}
    public Path saveRecording(Path file,ManualRecording recording)throws IOException{Properties p=new Properties();p.setProperty("format_version","2");p.setProperty("recording_id",recording.recordingId());p.setProperty("name",recording.name());p.setProperty("configuration_id",recording.configurationId());p.setProperty("seed",Long.toString(recording.seed()));p.setProperty("qualified",Boolean.toString(recording.qualified()));p.setProperty("configuration_status",recording.configurationStatus());p.setProperty("explanation",recording.explanation());p.setProperty("action_count",Integer.toString(recording.actions().size()));for(int i=0;i<recording.actions().size();i++){ManualAction a=recording.actions().get(i);p.setProperty("action."+i,a.sequence()+"|"+a.scientificIteration()+"|"+a.constraint().name()+"|"+a.oldRelaxationState()+"|"+a.newRelaxationState()+"|"+a.seed()+"|"+a.coordinateSnapshotRevision());}p.setProperty("event_count",Integer.toString(recording.events().size()));for(int i=0;i<recording.events().size();i++){ManualExperimentEvent e=recording.events().get(i);p.setProperty("event."+i,e.index()+"|"+e.scientificIteration()+"|"+e.type().name()+"|"+e.detail()+"|"+e.coordinateSnapshotRevision());}Path parent=file.toAbsolutePath().getParent();if(parent!=null)Files.createDirectories(parent);try(Writer writer=Files.newBufferedWriter(file,StandardCharsets.UTF_8)){p.store(writer,"REM Framework manual experiment recording");}return file;}
    public ManualRecording loadRecording(Path file)throws IOException{Properties p=new Properties();try(Reader reader=Files.newBufferedReader(file,StandardCharsets.UTF_8)){p.load(reader);}if(!Set.of("1","2").contains(p.getProperty("format_version")))throw new IOException("Unsupported manual recording format.");List<ManualAction> actions=new ArrayList<>();for(int i=0;i<Integer.parseInt(p.getProperty("action_count","0"));i++){String[] v=p.getProperty("action."+i).split("\\|",-1);ManualConstraint c=ManualConstraint.valueOf(v.length>2?v[2]:v[1]);int offset=v.length>2?1:0;actions.add(new ManualAction(Long.parseLong(v[0]),java.time.Instant.EPOCH,Integer.parseInt(v[1]),c,Boolean.parseBoolean(v[2+offset]),Boolean.parseBoolean(v[3+offset]),Set.of(),ManualVelocityPolicy.RESET_VELOCITY_ON_FORCE_CHANGE,Long.parseLong(v[4+offset]),Integer.parseInt(v[5+offset]),Map.of(),Map.of()));}List<ManualExperimentEvent> events=new ArrayList<>();for(int i=0;i<Integer.parseInt(p.getProperty("event_count","0"));i++){String[] v=p.getProperty("event."+i).split("\\|",-1);events.add(new ManualExperimentEvent(Long.parseLong(v[0]),java.time.Instant.EPOCH,Integer.parseInt(v[1]),ManualExperimentEvent.Type.valueOf(v[2]),v[3],Integer.parseInt(v[4])));}return new ManualRecording(p.getProperty("recording_id"),p.getProperty("name"),p.getProperty("configuration_id"),Long.parseLong(p.getProperty("seed")),actions,events,List.of(),Boolean.parseBoolean(p.getProperty("qualified")),p.getProperty("configuration_status",""),p.getProperty("explanation",""));}
    public Path save(Path file,ManualRelaxationRecord record)throws IOException{Properties p=new Properties();p.setProperty("format_version","1");p.setProperty("strategy",record.strategy().name());p.setProperty("velocity_policy",record.velocityPolicy().name());p.setProperty("active_force_set",record.activeForceSet().stream().map(Enum::name).sorted().reduce((a,b)->a+","+b).orElse(""));p.setProperty("final_qualification",Boolean.toString(record.finalQualification()));p.setProperty("configuration_status",record.configurationStatus());p.setProperty("explanation",record.explanation());p.setProperty("action_count",Integer.toString(record.actionHistory().size()));for(int i=0;i<record.actionHistory().size();i++){ManualAction a=record.actionHistory().get(i);p.setProperty("action."+i,a.sequence()+"|"+a.constraint().name()+"|"+a.oldRelaxationState()+"|"+a.newRelaxationState()+"|"+a.scientificIteration()+"|"+a.seed()+"|"+a.coordinateSnapshotRevision());}p.setProperty("snapshot_count",Integer.toString(record.snapshots().size()));for(int i=0;i<record.snapshots().size();i++){GeometrySnapshot s=record.snapshots().get(i);p.setProperty("snapshot."+i,s.snapshotId()+"|"+s.label()+"|"+s.iteration()+"|"+s.seed()+"|"+s.revision()+"|"+s.qualified());}Path parent=file.toAbsolutePath().getParent();if(parent!=null)Files.createDirectories(parent);try(Writer writer=Files.newBufferedWriter(file,StandardCharsets.UTF_8)){p.store(writer,"REM Framework manual relaxation experiment");}return file;}
    public ManualRelaxationRecord load(Path file)throws IOException{Properties p=new Properties();try(Reader reader=Files.newBufferedReader(file,StandardCharsets.UTF_8)){p.load(reader);}if(!"1".equals(p.getProperty("format_version")))throw new IOException("Unsupported manual-relaxation format.");List<ManualConstraint> active=p.getProperty("active_force_set","").isBlank()?List.of():Arrays.stream(p.getProperty("active_force_set").split(",")).map(ManualConstraint::valueOf).toList();List<ManualAction> actions=new ArrayList<>();for(int i=0;i<Integer.parseInt(p.getProperty("action_count","0"));i++){String[] v=p.getProperty("action."+i).split("\\|",-1);ManualConstraint c=ManualConstraint.valueOf(v[1]);actions.add(new ManualAction(Long.parseLong(v[0]),java.time.Instant.EPOCH,Integer.parseInt(v[4]),c,Boolean.parseBoolean(v[2]),Boolean.parseBoolean(v[3]),Set.copyOf(active),ManualVelocityPolicy.valueOf(p.getProperty("velocity_policy")),Long.parseLong(v[5]),Integer.parseInt(v[6]),Map.of(),Map.of()));}return new ManualRelaxationRecord(RealizationStrategy.valueOf(p.getProperty("strategy")),ManualVelocityPolicy.valueOf(p.getProperty("velocity_policy")),active,actions,List.of(),Boolean.parseBoolean(p.getProperty("final_qualification")),p.getProperty("configuration_status",""),p.getProperty("explanation",""));}
}
